+            return notEqual(left, right);
         }
-        if (leftNull) {
-            return false;
+
+        @LiteralParameters({"x", "y"})
+        @SqlType(StandardTypes.BOOLEAN)
+        public static boolean isDistinctFrom(
+                @BlockPosition @SqlType(value = "varchar(x)", nativeContainerType = Slice.class) Block left,
